<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:sans-serif;color:#17201a;padding:24px}.card{border:1px solid #cbd5d0;padding:24px}h1{color:#047857}table{width:100%;border-collapse:collapse;margin-top:20px}td{padding:8px;border-bottom:1px solid #e5e7eb}.amount{font-size:26px;color:#047857;font-weight:bold}</style></head><body><div class="card"><h1>Subscription payment receipt</h1><p>Platform receipt #{{ $entry->id }}</p><table><tr><td>Tenant</td><td>{{ $entry->tenant->name }}</td></tr><tr><td>Reference</td><td>{{ $entry->reference }}</td></tr><tr><td>Received at</td><td>{{ $entry->created_at->format('Y-m-d H:i') }}</td></tr><tr><td>Recorded by</td><td>{{ $entry->recordedBy?->name ?? 'Platform' }}</td></tr></table><p class="amount">{{ number_format($entry->credit_syp) }} SYP</p><p>This payment was credited to the tenant prepaid subscription balance.</p></div></body></html>
